// Base58 alphabet module (Bitcoin alphabet, same as Python base58 package).
export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
export const BASE = 58n;
export const ZERO_CHAR = ALPHABET[0];

// Map from character to its index, for decoding.
const indexMap = new Map();
for (let i = 0; i < ALPHABET.length; i++) {
  indexMap.set(ALPHABET[i], BigInt(i));
}

export function charValue(ch) {
  if (!indexMap.has(ch)) {
    throw new Error(`Invalid character ${JSON.stringify(ch)}`);
  }
  return indexMap.get(ch);
}

