// Base58 encoding module.
// Input: plain array of byte values (0-255). Output: base58 string.

import { ALPHABET, BASE, ZERO_CHAR } from './alphabet.mjs';

export function b58encode(bytes) {
  // Count leading zero bytes; each becomes one leading '1'.
  let leadingZeros = 0;
  while (leadingZeros < bytes.length && bytes[leadingZeros] === 0) {
    leadingZeros++;
  }

  // Interpret the remaining bytes as one big integer.
  let value = 0n;
  for (let i = leadingZeros; i < bytes.length; i++) {
    value = value * 256n + BigInt(bytes[i]);
  }

  // Repeated division by 58 to build the base58 digits.
  let encoded = '';
  while (value > 0n) {
    const mod = value % BASE;
    encoded = ALPHABET[Number(mod)] + encoded;
    value = value / BASE;
  }

  return ZERO_CHAR.repeat(leadingZeros) + encoded;
}

