// Base58 decoding module.
// Input: base58 string. Output: plain array of byte values (0-255).

import { BASE, ZERO_CHAR, charValue } from './alphabet.mjs';

export function b58decode(str) {
  // Count leading '1' characters; each becomes one zero byte.
  let leadingZeros = 0;
  while (leadingZeros < str.length && str[leadingZeros] === ZERO_CHAR) {
    leadingZeros++;
  }

  // Interpret the remaining characters as one big integer.
  let value = 0n;
  for (let i = leadingZeros; i < str.length; i++) {
    value = value * BASE + charValue(str[i]);
  }

  // Repeated division by 256 to recover the original bytes.
  const bytes = [];
  while (value > 0n) {
    bytes.unshift(Number(value % 256n));
    value = value / 256n;
  }

  for (let i = 0; i < leadingZeros; i++) {
    bytes.unshift(0);
  }
  return bytes;
}

