// Reproduce CPython's repr() of a bytes object, e.g. b'abc', b'\x00\xff',
// b"it's". Input: plain array of byte values (0-255). Output: repr string.

export function bytesRepr(bytes) {
  // Python prefers single quotes, switching to double quotes only when the
  // data contains a single quote but no double quote.
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (const byte of bytes) {
    if (byte === 0x5c) {
      out += '\\\\';
    } else if (byte === quote.charCodeAt(0)) {
      out += '\\' + quote;
    } else if (byte === 0x09) {
      out += '\\t';
    } else if (byte === 0x0a) {
      out += '\\n';
    } else if (byte === 0x0d) {
      out += '\\r';
    } else if (byte >= 0x20 && byte < 0x7f) {
      out += String.fromCharCode(byte);
    } else {
      out += '\\x' + byte.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

