// Minimal argparse-compatible command-line parser (required string options).
// Mirrors Python argparse behavior: supports "--name value" and "--name=value",
// prints usage/errors to stderr and exits with code 2 on failure, -h exits 0.

function progName() {
  const p = process.argv[1] || 'test15.mjs';
  const parts = p.split('/');
  return parts[parts.length - 1];
}

function usageLine(names) {
  const opts = names.map((n) => `--${n} ${n.toUpperCase()}`).join(' ');
  return `usage: ${progName()} [-h] ${opts}`;
}

function fail(names, message) {
  console.error(usageLine(names));
  console.error(`${progName()}: error: ${message}`);
  process.exit(2);
}

export function parseArgs(names) {
  const known = new Set(names);
  const values = {};
  const argv = process.argv.slice(2);

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      console.log(usageLine(names));
      console.log('');
      console.log('options:');
      console.log('  -h, --help  show this help message and exit');
      for (const n of names) {
        console.log(`  --${n} ${n.toUpperCase()}`);
      }
      process.exit(0);
    }

    let name = null;
    let value = null;
    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(2, eq);
        value = arg.slice(eq + 1);
      } else {
        name = arg.slice(2);
        if (i + 1 < argv.length) {
          value = argv[++i];
        } else {
          fail(names, `argument --${name}: expected one argument`);
        }
      }
    }
    if (name === null || !known.has(name)) {
      fail(names, `unrecognized arguments: ${arg}`);
    }
    values[name] = value;
  }

  const missing = names.filter((n) => !(n in values));
  if (missing.length > 0) {
    fail(
      names,
      `the following arguments are required: ${missing.map((n) => `--${n}`).join(', ')}`
    );
  }
  return values;
}

